  6002  /* Analyze type of the line and find some its properties. This serves as a
  6003   * main input for determining type and boundaries of a block. */
  6004  static int
  6005  md_analyze_line(MD_CTX* ctx, OFF beg, OFF* p_end,
  6006                  const MD_LINE_ANALYSIS* pivot_line, MD_LINE_ANALYSIS* line)
  6007  {
  6008      unsigned total_indent = 0;
  6009      int n_parents = 0;
  6010      int n_brothers = 0;
  6011      int n_children = 0;
  6012      MD_CONTAINER container = { 0 };
  6013      int prev_line_has_list_loosening_effect = ctx->last_line_has_list_loosening_effect;
  6014      OFF off = beg;
  6015      OFF hr_killer = 0;
  6016      int ret = 0;
  6017
  6018      line->indent = md_line_indentation(ctx, total_indent, off, &off);
  6019      total_indent += line->indent;
  6020      line->beg = off;
  6021      line->enforce_new_block = FALSE;
  6022
  6023      /* Given the indentation and block quote marks '>', determine how many of
  6024       * the current containers are our parents. */
