  6026          MD_CONTAINER* c = &ctx->containers[n_parents];
  6027
  6028          if(c->ch == _T('>')  &&  line->indent < ctx->code_indent_offset  &&
  6029              off < ctx->size  &&  CH(off) == _T('>'))
  6030          {
  6525          ((MD_LINE_ANALYSIS*)pivot_line)->type = MD_LINE_TABLE;
  6526          MD_CHECK(md_add_line_into_current_block(ctx, line));
